package accurate_test

import (
	"crypto/sha256"
	"fmt"
	"testing"

	"github.com/awang-karisma/cim-warehouse-barcode/pkg/accurate"
)

// These exact vectors were evaluated with the public 6041 nucauth.js
// JSON.stringify + btoa implementation, not generated by the Go encoder.
func TestNucauthMatchesBrowserBytes(t *testing.T) {
	for _, tc := range []struct {
		name, password, pre, post, otp string
	}{
		{
			name: "JSON escaping", password: "ascii<>&\"\\\n",
			pre:  "upeyJ2IjoxLCJwIjoiYXNjaWk8PiZcIlxcXG4iLCJkIjoiZml4dHVyZS1kZXZpY2UifQ==",
			post: "uaeyJ2IjoxLCJwIjoiYXNjaWk8PiZcIlxcXG4iLCJjIjoiZml4dHVyZS1wZXJtaXQiLCJ0IjpudWxsLCJkIjoiZml4dHVyZS1kZXZpY2UifQ==",
			otp:  "uaeyJ2IjoxLCJwIjoiYXNjaWk8PiZcIlxcXG4iLCJjIjoiZml4dHVyZS1wZXJtaXQiLCJ0IjoiMTIzNDU2IiwiZCI6ImZpeHR1cmUtZGV2aWNlIn0=",
		},
		{
			name: "Latin-1", password: "caf\u00e9\u00a3\u00ff",
			pre:  "upeyJ2IjoxLCJwIjoiY2Fm6aP/IiwiZCI6ImZpeHR1cmUtZGV2aWNlIn0=",
			post: "uaeyJ2IjoxLCJwIjoiY2Fm6aP/IiwiYyI6ImZpeHR1cmUtcGVybWl0IiwidCI6bnVsbCwiZCI6ImZpeHR1cmUtZGV2aWNlIn0=",
			otp:  "uaeyJ2IjoxLCJwIjoiY2Fm6aP/IiwiYyI6ImZpeHR1cmUtcGVybWl0IiwidCI6IjEyMzQ1NiIsImQiOiJmaXh0dXJlLWRldmljZSJ9",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			pre, err := accurate.NucauthPre(tc.password, "fixture-device")
			if err != nil || pre != tc.pre {
				t.Error("pre-login bytes differ from the public JavaScript codec")
			}
			post, err := accurate.NucauthPost(tc.password, "fixture-permit", nil, "fixture-device")
			if err != nil || post != tc.post {
				t.Error("authentication bytes differ from the public JavaScript codec")
			}
			otp := "123456"
			post, err = accurate.NucauthPost(tc.password, "fixture-permit", &otp, "fixture-device")
			if err != nil || post != tc.otp {
				t.Error("MFA bytes differ from the public JavaScript codec")
			}
		})
	}
}

func TestNucauthRejectsStringsUnsupportedByBrowser(t *testing.T) {
	for _, value := range []string{"\u6f22", "\u2028", "\U0001f600", string([]byte{0xff})} {
		if _, err := accurate.NucauthPre(value, "fixture-device"); err == nil {
			t.Error("pre-login accepted a password that browser btoa cannot encode")
		}
		for _, args := range [][3]string{
			{value, "fixture-permit", "fixture-device"},
			{"fixture-password", value, "fixture-device"},
			{"fixture-password", "fixture-permit", value},
		} {
			if _, err := accurate.NucauthPost(args[0], args[1], nil, args[2]); err == nil {
				t.Error("authentication accepted a string that browser btoa cannot encode")
			}
		}
		if _, err := accurate.NucauthPost("fixture-password", "fixture-permit", &value, "fixture-device"); err == nil {
			t.Error("authentication accepted an OTP that browser btoa cannot encode")
		}
	}
}

func TestNucauthMatchesBrowserEntireLatin1Range(t *testing.T) {
	var password []rune
	for r := rune(0); r <= 255; r++ {
		password = append(password, r)
	}
	// SHA-256 of exact public JSON.stringify+btoa output, evaluated in Node.
	for _, tc := range []struct {
		name, want string
		encode     func() (string, error)
	}{
		{"pre", "f79086047ce73c672dc6ab637bab3fad9cad87cbfe4fee1dfe0b98d39c167be7", func() (string, error) {
			return accurate.NucauthPre(string(password), "fixture-device")
		}},
		{"post", "850cc14193e300b7291b869a13a35d7d422a1796c109819e5f6b01bdfb51e56c", func() (string, error) {
			return accurate.NucauthPost(string(password), "fixture-permit", nil, "fixture-device")
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			encoded, err := tc.encode()
			if err != nil || fmt.Sprintf("%x", sha256.Sum256([]byte(encoded))) != tc.want {
				t.Error("codec differs from browser on control characters or Latin-1 bytes")
			}
		})
	}
}
